const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define UK geometry (approximate bounding box)
  const uk = ee.Geometry.Polygon([
    [[-8.5, 49.5], [2.0, 49.5], [2.0, 61.0], [-8.5, 61.0], [-8.5, 49.5]]
  ]);

  // 2. Get ERA5 temperature data for July 19, 2022
  const startDate = '2022-07-19';
  const endDate = '2022-07-20';

  const tempCollection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(uk)
    .select('temperature_2m');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No temperature data available for July 19, 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get maximum temperature across all hours of the day
  const maxTemp = tempCollection.max();

  // 4. Calculate statistics over UK
  const stats = maxTemp.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: uk,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const maxTempK = stats['temperature_2m_max'];
  const pixelCount = stats['temperature_2m_count'];

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels found.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (maxTempK === null || maxTempK === undefined) {
    console.log('Temperature calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Convert to Fahrenheit and check
  const maxTempC = maxTempK - 273.15;
  const maxTempF = maxTempC * 9/5 + 32;

  console.log(`Max temperature: ${maxTempK.toFixed(2)}K = ${maxTempC.toFixed(2)}°C = ${maxTempF.toFixed(2)}°F`);

  // Sanity check
  if (maxTempK < 250 || maxTempK > 330) {
    console.log('Temperature out of reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Final answer
  if (maxTempF > 100) {
    console.log('UK experienced temperatures above 100°F on July 19, 2022.');
    console.log('<answer>A</answer>');
  } else {
    console.log('UK did NOT experience temperatures above 100°F on July 19, 2022.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
